import AppKit

/// One drawable primitive inside a glyph (path / circle / rounded-rect), in SVG (y-down) coords.
struct GlyphShape {
    enum Kind {
        case path(String)
        case circle(cx: CGFloat, cy: CGFloat, r: CGFloat)
        case rect(x: CGFloat, y: CGFloat, w: CGFloat, h: CGFloat, rx: CGFloat)
    }
    let kind: Kind
    var evenOdd: Bool = false
    /// rotation in degrees around (cx, cy) applied in SVG space
    var rotate: (deg: CGFloat, cx: CGFloat, cy: CGFloat)? = nil
    /// when set, this shape is stroked with the given color instead of filled with the glyph color
    var strokeColor: NSColor? = nil
    var strokeWidth: CGFloat = 0
    /// when true, this shape is stroked with the glyph's dynamic color instead of filled
    var strokeWithColor: Bool = false
}

struct GlyphDef {
    let viewBox: CGFloat
    let shapes: [GlyphShape]
    init(_ shapes: [GlyphShape]) {
        self.viewBox = 20
        self.shapes = shapes
    }
    init(_ viewBox: CGFloat, _ shapes: [GlyphShape]) {
        self.viewBox = viewBox
        self.shapes = shapes
    }
}

enum Glyphs {
    static func def(_ name: String) -> GlyphDef? { registry[name] }

    static let registry: [String: GlyphDef] = build()

    private static func p(_ d: String, evenOdd: Bool = false) -> GlyphShape {
        GlyphShape(kind: .path(d), evenOdd: evenOdd)
    }
    private static func circle(_ cx: CGFloat, _ cy: CGFloat, _ r: CGFloat) -> GlyphShape {
        GlyphShape(kind: .circle(cx: cx, cy: cy, r: r))
    }
    private static func rect(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat, _ rx: CGFloat,
                             rotate: (CGFloat, CGFloat, CGFloat)? = nil) -> GlyphShape {
        var s = GlyphShape(kind: .rect(x: x, y: y, w: w, h: h, rx: rx))
        if let r = rotate { s.rotate = (deg: r.0, cx: r.1, cy: r.2) }
        return s
    }

