    private static func strokeCircle(_ cx: CGFloat, _ cy: CGFloat, _ r: CGFloat, _ width: CGFloat) -> GlyphShape {
        var s = GlyphShape(kind: .circle(cx: cx, cy: cy, r: r))
        s.strokeWithColor = true
        s.strokeWidth = width
        return s
    }

    private static func stroke(_ d: String, _ width: CGFloat) -> GlyphShape {
        var s = GlyphShape(kind: .path(d))
        s.strokeWithColor = true
        s.strokeWidth = width
        return s
    }

    private static func strokeRect(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat,
                                   _ rx: CGFloat, _ width: CGFloat) -> GlyphShape {
        var s = GlyphShape(kind: .rect(x: x, y: y, w: w, h: h, rx: rx))
        s.strokeWithColor = true
        s.strokeWidth = width
        return s
    }
}

/// Renders a glyph by name, filling fillable shapes with `color` (defaults to fgNeutral).
final class GlyphView: NSView {
    private(set) var glyphName: String
    var color: NSColor {
        didSet { needsDisplay = true }
    }
    /// Clockwise rotation (degrees) of the whole glyph around its center.
    var rotationDegrees: CGFloat = 0 {
        didSet { needsDisplay = true }
    }

    init(name: String, size: CGFloat = 20, color: NSColor? = nil) {
        self.glyphName = name
        self.color = color ?? ThemeManager.shared.theme.fgNeutral
        super.init(frame: NSRect(x: 0, y: 0, width: size, height: size))
        self.wantsLayer = true
    }

    required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }

    func setName(_ name: String) {
        glyphName = name
        needsDisplay = true
    }

    func setSize(_ size: CGFloat) {
        setFrameSize(NSSize(width: size, height: size))
        needsDisplay = true
    }

    override var isFlipped: Bool { false }

    override func draw(_ dirtyRect: NSRect) {
        super.draw(dirtyRect)
        guard let def = Glyphs.def(glyphName) else { return }
        let vb = def.viewBox
        let sx = bounds.width / vb
        let sy = bounds.height / vb

        // SVG y-down → AppKit y-up: flip vertically and scale to bounds.
        let transform = NSAffineTransform()
        transform.translateX(by: 0, yBy: bounds.height)
        transform.scaleX(by: sx, yBy: -sy)

        for shape in def.shapes {
            let basePath = buildPath(for: shape)
            // apply per-shape rotation (in SVG space) first
            if let rot = shape.rotate {
                let r = NSAffineTransform()
                r.translateX(by: rot.cx, yBy: rot.cy)
                r.rotate(byDegrees: rot.deg)
                r.translateX(by: -rot.cx, yBy: -rot.cy)
                basePath.transform(using: r as AffineTransform)
            }
            basePath.transform(using: transform as AffineTransform)
            if rotationDegrees != 0 {
                let cx = bounds.width / 2, cy = bounds.height / 2
                let rot = NSAffineTransform()
                rot.translateX(by: cx, yBy: cy)
                rot.rotate(byDegrees: -rotationDegrees)
                rot.translateX(by: -cx, yBy: -cy)
                basePath.transform(using: rot as AffineTransform)
            }
            basePath.windingRule = shape.evenOdd ? .evenOdd : .nonZero

            if shape.strokeWithColor {
                color.setStroke()
                basePath.lineWidth = shape.strokeWidth * ((sx + sy) / 2)
                basePath.lineCapStyle = .round
                basePath.lineJoinStyle = .round
                basePath.stroke()
            } else if let stroke = shape.strokeColor {
                stroke.setStroke()
                basePath.lineWidth = shape.strokeWidth * ((sx + sy) / 2)
                basePath.lineCapStyle = .round
                basePath.lineJoinStyle = .round
                basePath.stroke()
            } else {
                color.setFill()
                basePath.fill()
            }
        }
    }

    private func buildPath(for shape: GlyphShape) -> NSBezierPath {
        switch shape.kind {
        case .path(let d):
            return SVGPath.parse(d)
        case .circle(let cx, let cy, let r):
            return NSBezierPath(ovalIn: NSRect(x: cx - r, y: cy - r, width: r * 2, height: r * 2))
        case .rect(let x, let y, let w, let h, let rx):
            return NSBezierPath(roundedRect: NSRect(x: x, y: y, width: w, height: h), xRadius: rx, yRadius: rx)
        }
    }
}
